// WP-9.1 neural inference on the GPU: see include/fuse/renderer/neural/neural_gpu.hpp.
#include <fuse/renderer/neural/neural_gpu.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>

// Generated by cmake/rp_wp91.cmake from shaders/neural/*: kNnInfer<Slang|Glsl>Spv, kNnInferCoopGlslSpv and
// FUSE_NEURAL_{SLANG,GLSL,COOPMAT} for the kernels that were built.
#include "neural_spv.h"

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>
#endif

namespace fuse::renderer::neural {

namespace {
[[maybe_unused]] constexpr u32 kPushBytes = sizeof(NeuralPush);

u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }

BufferUsage ringUsage() {
    return static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) |
                                    static_cast<u32>(BufferUsage::ShaderDeviceAddress) |
                                    static_cast<u32>(BufferUsage::TransferSrc));
}

/// The cooperative-matrix kernel's constraints (nn_infer_coopmat.comp).
bool coopEligible(const NeuralNet& net) {
    const NeuralGpuHeader& h = net.header();
    if (h.paramPrecision != static_cast<u32>(NeuralPrecision::F16) || h.layerCount < 2u) {
        return false;
    }
    for (u32 j = 0; j + 1u < h.layerCount; ++j) {
        if ((h.layerIn[j] % kNnCoopTile) != 0u || (h.layerOut[j] % kNnCoopTile) != 0u) {
            return false;
        }
    }
    return true;
}
} // namespace

const u32* neuralCoopMatrixSpirv(usize* bytes) {
#if defined(FUSE_NEURAL_COOPMAT)
    if (bytes != nullptr) {
        *bytes = sizeof(kNnInferCoopGlslSpv);
    }
    return kNnInferCoopGlslSpv;
#else
    if (bytes != nullptr) {
        *bytes = 0;
    }
    return nullptr;
#endif
}

NeuralCapabilities queryNeuralCapabilities(const VulkanDevice* device) {
    NeuralCapabilities c{};
#if defined(FUSE_NEURAL_COOPMAT)
    c.coopMatrixKernelBuilt = true;
#endif
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    const RendererCaps& caps = device->info().caps;
    if (!caps.bufferDeviceAddress || !caps.shaderInt64) {
        c.reason = "bufferDeviceAddress / shaderInt64 missing";
        return c;
    }
    c.gpu = true;
    c.cooperativeMatrix = caps.cooperativeMatrix && c.coopMatrixKernelBuilt;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

NeuralGpu::~NeuralGpu() { destroy(); }

bool NeuralGpu::init(const NeuralGpuDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.framesInFlight == 0u || desc.framesInFlight > kMaxSlots) {
        return false;
    }
    if (!queryNeuralCapabilities(desc.device).gpu) {
        return false;
    }
    m_retired.reserve(8);
    m_initialized = true; // destroy() releases partial state from here on
    if (!createPipelines() || !ensureCapacity(std::max<u64>(desc.initialSlotBytes, 4096u))) {
        destroy();
        return false;
    }
    return true;
#else
    return false;
#endif
}

void NeuralGpu::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    if (m_ring.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_ring);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void* p : {m_pipeline, m_coopPipeline}) {
        if (p != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(p), nullptr);
        }
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_pipeline = nullptr;
    m_coopPipeline = nullptr;
    m_layoutHandle = nullptr;
    m_ring = Buffer{};
    m_ringQueue = rg::kNoQueue;
    m_slotStride = 0;
    m_slot = 0;
    for (u64& v : m_slotVersion) {
        v = 0u;
    }
    m_slotBytes = 0;
    m_inputDims = 0;
    m_outputDims = 0;
    m_coopEligible = false;
    m_retired.clear();
    m_recordCount = 0;
    m_language = "none";
    m_stats = NeuralGpuStats{};
    m_initialized = false;
}

bool NeuralGpu::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    const u32* words = nullptr;
    usize bytes = 0;
#if defined(FUSE_NEURAL_SLANG)
    if (m_desc.language == NeuralKernelLanguage::Auto || m_desc.language == NeuralKernelLanguage::Slang) {
        words = kNnInferSlangSpv;
        bytes = sizeof(kNnInferSlangSpv);
        m_language = "slang";
    }
#endif
#if defined(FUSE_NEURAL_GLSL)
    if (words == nullptr &&
        (m_desc.language == NeuralKernelLanguage::Auto || m_desc.language == NeuralKernelLanguage::Glsl)) {
        words = kNnInferGlslSpv;
        bytes = sizeof(kNnInferGlslSpv);
        m_language = "glsl";
    }
#endif
    if (words == nullptr) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout =
        m_desc.bindless != nullptr ? static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle()) : VK_NULL_HANDLE;
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    auto build = [&](const u32* code, usize codeBytes, void*& out) {
        VkShaderModuleCreateInfo moduleInfo{};
        moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        moduleInfo.codeSize = codeBytes;
        moduleInfo.pCode = code;
        VkShaderModule module = VK_NULL_HANDLE;
        if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags =
            m_desc.bindless != nullptr ? static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags()) : 0u;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = module;
        info.stage.pName = "main";
        info.layout = layout;
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, module, nullptr);
        out = pipeline;
        return result == VK_SUCCESS;
    };
    if (!build(words, bytes, m_pipeline)) {
        return false;
    }
    if (m_desc.allowCooperativeMatrix && queryNeuralCapabilities(m_desc.device).cooperativeMatrix) {
        usize coopBytes = 0;
        const u32* coop = neuralCoopMatrixSpirv(&coopBytes);
        if (coop != nullptr && !build(coop, coopBytes, m_coopPipeline)) {
            m_coopPipeline = nullptr; // the portable kernel stays in use
        }
    }
    return true;
#else
    return false;
#endif
}

bool NeuralGpu::ensureCapacity(u64 slotBytes) {
    if (m_ring.handle != nullptr && slotBytes <= m_slotStride) {
        return true;
    }
    const u64 stride = align256(std::max<u64>(slotBytes + slotBytes / 4u, 4096u));
    BufferDesc d{};
    d.size = static_cast<usize>(stride * m_desc.framesInFlight);
    d.usage = ringUsage();
    d.memoryUsage = MemoryUsage::CpuToGpu;
    d.name = "neural.ring";
    Buffer fresh{};
    if (!m_desc.allocator->createBuffer(d, fresh) || fresh.mapped == nullptr || fresh.deviceAddress == 0u) {
        if (fresh.handle != nullptr) {
            m_desc.allocator->destroyBuffer(fresh);
        }
        return false;
    }
    if (m_ring.handle != nullptr) {
        m_retired.push_back(Retired{m_ring, m_frameSerial});
        ++m_stats.retired;
        ++m_stats.reallocations;
    }
    m_ring = fresh;
    m_ringQueue = rg::kNoQueue;
    m_slotStride = stride;
    for (u64& v : m_slotVersion) {
        v = 0u;
    }
    return true;
}

bool NeuralGpu::beginFrame(u64 frameSerial, const NeuralNet& net) {
    if (!m_initialized || !net.valid()) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_recordCount = 0;
    m_stats.passes = 0;
    m_stats.coopPasses = 0;
    const u64 bytes = net.gpuBlobBytes();
    if (!ensureCapacity(bytes)) {
        return false;
    }
    m_slot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    if (m_slotVersion[m_slot] != net.version()) {
        net.writeGpuBlob(static_cast<u8*>(m_ring.mapped) + static_cast<u64>(m_slot) * m_slotStride);
        m_slotVersion[m_slot] = net.version();
        ++m_stats.uploads;
        m_stats.uploadBytes += bytes;
    }
    m_slotBytes = bytes;
    m_inputDims = net.header().inputDims;
    m_outputDims = net.header().outputDims;
    m_coopEligible = coopEligible(net);
    return true;
}

NeuralGraphRefs NeuralGpu::importInto(rg::Graph& graph) {
    NeuralGraphRefs refs{};
    if (!m_initialized || m_ring.handle == nullptr) {
        return refs;
    }
    refs.net = graph.importBuffer(
        rg::ImportedBuffer{m_ring.handle, m_ring.desc.size, m_ringQueue, &m_ringQueue, "neural.ring"});
    const u64 base = static_cast<u64>(m_slot) * m_slotStride;
    refs.range = rg::BufferRange{base, m_slotStride};
    refs.header = m_ring.deviceAddress + base;
    refs.params = refs.header + sizeof(NeuralGpuHeader);
    return refs;
}

bool NeuralGpu::addInferPass(rg::Graph& graph, const NeuralGraphRefs& refs, rg::BufferRef inputs, u64 inputsOffset,
                             u64 inputsAddress, rg::BufferRef outputs, u64 outputsOffset, u64 outputsAddress,
                             u32 count) {
    if (!m_initialized || !refs.net.valid() || !inputs.valid() || !outputs.valid() || count == 0u ||
        inputsAddress == 0u || outputsAddress == 0u || m_recordCount >= kMaxPasses || m_inputDims == 0u) {
        return false;
    }
    PassRecord& r = m_records[m_recordCount++];
    r = PassRecord{};
    r.self = this;
    r.push.header = refs.header;
    r.push.params = refs.params;
    r.push.inputs = inputsAddress;
    r.push.outputs = outputsAddress;
    r.push.count = count;
    r.coop = m_coopPipeline != nullptr && m_coopEligible;
    r.groups = r.coop ? (count + kNnCoopTile - 1u) / kNnCoopTile : (count + kNnWorkgroup - 1u) / kNnWorkgroup;
    ++m_stats.passes;
    if (r.coop) {
        ++m_stats.coopPasses;
    }
    graph.addPass("neural.infer", &NeuralGpu::recordDispatch, &r)
        .use(refs.net, rg::Access::StorageRead, refs.range, rg::kStageCompute)
        .use(inputs, rg::Access::StorageRead,
             rg::BufferRange{inputsOffset, static_cast<u64>(count) * m_inputDims * sizeof(f32)}, rg::kStageCompute)
        .use(outputs, rg::Access::StorageWrite,
             rg::BufferRange{outputsOffset, static_cast<u64>(count) * m_outputDims * sizeof(f32)}, rg::kStageCompute);
    return true;
}

void NeuralGpu::recordDispatch(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const NeuralGpu& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE,
                      static_cast<VkPipeline>(r.coop ? self.m_coopPipeline : self.m_pipeline));
    if (self.m_desc.bindless != nullptr) {
        self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    }
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0,
                       kPushBytes, &r.push);
    vkCmdDispatch(cmd, r.groups, 1u, 1u);
#else
    (void)context;
    (void)user;
#endif
}

u32 NeuralGpu::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        if (m_retired[i].buffer.handle != nullptr) {
            m_desc.allocator->destroyBuffer(m_retired[i].buffer);
        }
        ++collected;
    }
    m_retired.resize(keep);
    m_stats.retired = m_stats.retired >= collected ? m_stats.retired - collected : 0u;
    return collected;
}

} // namespace fuse::renderer::neural
